<?php
$title='Leads';$subtitle='Your CRM – enquiries from forms, ads, bookings and won prospects';
$adm=can('settings');$me=user();
if(is_post()){
  $a=$_POST['a']??'';
  try{
  $ids=array_map('intval',$_POST['ids']??[]);
  if(!$adm&&$ids)$ids=array_column(DB::all('SELECT l.id FROM leads l WHERE l.id IN ('.implode(',',$ids).')'.scope()),'id');
  if(strpos($a,'auto:')===0&&can('automations')){$au=DB::row('SELECT * FROM automations WHERE id=?',[(int)substr($a,5)]);$n=0;if($au)foreach($ids as $i)if(Automation::start($au,$i,true))$n++;flash($n.' lead(s) added to automation "'.e($au['name']??'').'".');}
  elseif(strpos($a,'own:')===0&&$adm){$u=(int)substr($a,4)?:null;foreach($ids as $i){DB::update('leads',['assigned_to'=>$u],'id=?',[$i]);event($i,'note','Owner changed to '.($u?DB::val('SELECT name FROM users WHERE id=?',[$u]):'nobody'));}flash(count($ids).' lead(s) reassigned.');}
  elseif(strpos($a,'status:')===0){foreach($ids as $i)CRM::setStatus($i,substr($a,7));flash(count($ids).' lead(s) updated.');}
  elseif($a==='initiate'&&can('prospecting')&&mod('prospecting')){flash(Outreach::initiate($ids,['auto'=>0]).' lead(s) queued for audit & report.');}
  elseif($a==='delete'&&$adm)flash(e(Outreach::bulk('delete',$ids)));
  else throw new Exception('You cannot do that.');}
  catch(Throwable $e){flash(e($e->getMessage()),'err');}
  back(url('leads'));}
$view=($_GET['view']??($_COOKIE['lv']??'list'))==='board'?'board':'list';
setcookie('lv',$view,time()+86400*365,'/');
$q=trim($_GET['q']??'');$st=$_GET['status']??'';$src=$_GET['src']??'';$tag=trim($_GET['tag']??'');$own=$_GET['own']??'';$fu=$_GET['fu']??'';
$w=['l.is_lead=1'.scope()];$a=[];
if($q!==''){$w[]='(l.name LIKE ? OR l.contact_name LIKE ? OR l.email LIKE ? OR l.phone LIKE ? OR l.city LIKE ? OR l.tags LIKE ? OR l.custom LIKE ?)';array_push($a,...array_fill(0,7,'%'.$q.'%'));}
if(isset(crm_statuses()[$st])&&$view==='list'){$w[]='l.status=?';$a[]=$st;}
if(isset(lead_sources()[$src])){$w[]='l.source=?';$a[]=$src;}
if($tag!==''){$w[]='l.tags LIKE ?';$a[]='%'.$tag.'%';}
if($own==='me'){$w[]='l.assigned_to=?';$a[]=$me['id'];}elseif($own==='none')$w[]='l.assigned_to IS NULL';elseif((int)$own&&$adm){$w[]='l.assigned_to=?';$a[]=(int)$own;}
if($fu==='due')$w[]="l.follow_up_at IS NOT NULL AND l.follow_up_at<=NOW() AND l.status NOT IN ('won','lost')";
$where=implode(' AND ',$w);
if(isset($_GET['export'])&&$adm)Outreach::csv(DB::all("SELECT l.* FROM leads l WHERE $where ORDER BY l.id DESC",$a));
$total=(int)DB::val("SELECT COUNT(*) FROM leads l WHERE $where",$a);
$per=$view==='board'?500:50;$pg=max(1,(int)($_GET['p']??1));$pages=max(1,(int)ceil($total/$per));
$leads=DB::all("SELECT l.*,u.name owner FROM leads l LEFT JOIN users u ON u.id=l.assigned_to WHERE $where ORDER BY COALESCE(l.lead_at,l.created_at) DESC,l.id DESC LIMIT $per OFFSET ".(($pg-1)*$per),$a);
$sc=[];foreach(DB::all('SELECT l.source,COUNT(*) n FROM leads l WHERE l.is_lead=1'.scope().' GROUP BY l.source') as $r)$sc[$r['source']]=(int)$r['n'];
$k=DB::row("SELECT COUNT(*) t,SUM(l.status='new') nw,SUM(l.created_at>=CURDATE()) td,SUM(l.status='won') wn,SUM(CASE WHEN l.status='won' THEN l.deal_value ELSE 0 END) wv,SUM(CASE WHEN l.status NOT IN ('won','lost') THEN l.deal_value ELSE 0 END) pv,SUM(l.follow_up_at IS NOT NULL AND l.follow_up_at<=NOW() AND l.status NOT IN ('won','lost')) due,SUM(l.assigned_to IS NULL) un FROM leads l WHERE l.is_lead=1".scope());
$users=$adm?DB::all('SELECT id,name FROM users WHERE active=1 ORDER BY name'):[];
$autos=can('automations')?DB::all('SELECT id,name FROM automations ORDER BY name'):[];
$qs=fn($x)=>url('leads',array_filter(array_merge(['q'=>$q,'status'=>$st,'src'=>$src,'tag'=>$tag,'own'=>$own,'fu'=>$fu,'view'=>$view],$x),'strlen'));
$cc=['blue'=>'blue','teal'=>'teal','purple'=>'violet','orange'=>'orange','gold'=>'amber','green'=>'green','red'=>'rose'];
$nf=count(array_filter([$q,$view==='list'?$st:'',$tag,$own,$fu],'strlen'));
?>
<div class="stats"><?=kpi(role()==='sales'?'My leads':'Total leads',number_format((int)$k['t']),'users','indigo',(int)$k['td'].' added today')?><?=kpi('New / uncontacted',(int)$k['nw'],'zap','sky','need a first touch',$qs(['status'=>'new','view'=>'list']))?><?=kpi('Follow-ups due',(int)$k['due'],'clock','orange',$k['due']?'<span class="dn">overdue or today</span>':'all caught up',$qs(['fu'=>'due']))?><?=kpi('Open pipeline',money($k['pv']),'kanban','violet',$adm?(int)$k['un'].' unassigned':'deal value in progress',$qs(['view'=>'board']))?><?=kpi('Won',money($k['wv']),'target','green',(int)$k['wn'].' deals',$qs(['status'=>'won','view'=>'list']))?></div>
<div class="ph"><div class="seg"><a href="<?=$qs(['view'=>'list'])?>" class="<?=$view==='list'?'on':''?>"><?=icon('list')?>List</a><a href="<?=$qs(['view'=>'board'])?>" class="<?=$view==='board'?'on':''?>"><?=icon('kanban')?>Board</a></div><div class="pha"><?php if($adm):?><a class="btn" href="<?=url('lead_new',['tab'=>'import'])?>"><?=icon('upload')?>Import</a><a class="btn" href="<?=$qs(['export'=>1])?>"><?=icon('download')?>Export</a><?php endif?><a class="btn btn-p" href="<?=url('lead_new')?>"><?=icon('plus')?>Add lead</a></div></div>
<div class="chips"><a href="<?=$qs(['src'=>''])?>" class="all c-indigo <?=$src===''?'on':''?>">All sources <em><?=array_sum($sc)?></em></a><?php foreach(lead_sources() as $kk=>[$lb,$c,$ic]):if(empty($sc[$kk])&&$src!==$kk)continue;?><a href="<?=$qs(['src'=>$kk])?>" class="src-<?=$c?> <?=$src===$kk?'on':''?>"><?=icon($ic)?><?=e($lb)?> <em><?=$sc[$kk]??0?></em></a><?php endforeach?></div>
<form class="fbar" method="get"><input type="hidden" name="r" value="leads"><input type="hidden" name="view" value="<?=$view?>"><input type="hidden" name="src" value="<?=e($src)?>"><label class="srch"><?=icon('search')?><input name="q" value="<?=e($q)?>" placeholder="Search name, phone, email, city, tag or any field…"></label><?php if($view==='list'):?><select name="status" class="<?=$st?'on':''?>" onchange="this.form.submit()"><option value="">Any status</option><?php foreach(crm_statuses() as $kk=>[$lb]):?><option value="<?=$kk?>" <?=$st===$kk?'selected':''?>><?=e($lb)?></option><?php endforeach?></select><?php endif?><select name="own" class="<?=$own?'on':''?>" onchange="this.form.submit()"><option value="">Any owner</option><option value="me" <?=$own==='me'?'selected':''?>>Assigned to me</option><option value="none" <?=$own==='none'?'selected':''?>>Unassigned</option><?php foreach($users as $u):if($u['id']==$me['id'])continue;?><option value="<?=$u['id']?>" <?=$own===(string)$u['id']?'selected':''?>><?=e($u['name'])?></option><?php endforeach?></select><select name="fu" class="<?=$fu?'on':''?>" onchange="this.form.submit()"><option value="">Any follow-up</option><option value="due" <?=$fu==='due'?'selected':''?>>Follow-up due</option></select><input name="tag" value="<?=e($tag)?>" placeholder="Tag" class="<?=$tag!==''?'on':''?>" style="width:110px"><?php if($nf):?><a class="clr-f" href="<?=url('leads',['view'=>$view,'src'=>$src])?>">Clear (<?=$nf?>)</a><?php endif?><span class="sep"></span><button class="btn btn-n"><?=icon('filter')?>Apply</button></form>
<?php if($view==='board'):$cols=[];foreach($leads as $l)$cols[$l['status']][]=$l;?>
<div class="kb"><?php foreach(crm_statuses() as $kk=>[$lb,$c]):$list=$cols[$kk]??[];$sum=array_sum(array_column($list,'deal_value'));?><div class="kc c-<?=$cc[$c]?>" data-status="<?=$kk?>"><div class="kc-h"><span><i></i><?=e($lb)?></span><em><?=count($list)?></em></div><?php if($sum):?><small class="muted xs" style="display:block;padding:0 6px 8px;margin-top:-6px"><?=money($sum)?></small><?php endif?><?php foreach($list as $l):?><div class="kcard" data-id="<?=$l['id']?>"><a href="<?=url('lead',['id'=>$l['id']])?>"><b><?=e($l['contact_name']?:$l['name'])?></b></a><small><?=e($l['contact_name']&&$l['name']!==$l['contact_name']?$l['name']:($l['phone']?:$l['email']))?></small><div class="km"><?=srcbadge($l['source'])?><?php if($l['deal_value']):?><b class="sm"><?=money($l['deal_value'])?></b><?php endif?></div><?php if($l['follow_up_at']):?><small class="<?=strtotime($l['follow_up_at'])<=time()?'red':''?>" style="margin-top:4px"><?=icon('clock')?><?=date('d M, h:i A',strtotime($l['follow_up_at']))?></small><?php endif?><?php if($l['owner']):?><small><?=icon('user')?><?=e($l['owner'])?></small><?php endif?></div><?php endforeach?></div><?php endforeach?></div>
<?php else:?>
<div class="card p0"><form id="bulk" method="post" class="bulk"><?=csrf_field()?><input type="hidden" name="a" id="bulk-a"><span class="bsel"><b id="selc">0</b> selected</span><div class="dd l"><button type="button" class="btn btn-sm" onclick="this.parentNode.classList.toggle('open')"><?=icon('target')?>Set status ▾</button><div class="ddm"><?php foreach(crm_statuses() as $kk=>[$lb]):?><button type="button" onclick="A.bulk('status:<?=$kk?>')"><?=e($lb)?></button><?php endforeach?></div></div><?php if($users):?><div class="dd l"><button type="button" class="btn btn-sm" onclick="this.parentNode.classList.toggle('open')"><?=icon('user')?>Assign ▾</button><div class="ddm"><?php foreach($users as $u):?><button type="button" onclick="A.bulk('own:<?=$u['id']?>')"><?=e($u['name'])?></button><?php endforeach?><hr><button type="button" onclick="A.bulk('own:0')">Unassign</button></div></div><?php endif?><?php if($autos):?><div class="dd l"><button type="button" class="btn btn-sm" onclick="this.parentNode.classList.toggle('open')"><?=icon('bot')?>Automation ▾</button><div class="ddm"><?php foreach($autos as $au):?><button type="button" onclick="A.bulk('auto:<?=$au['id']?>','Start this automation for the selected leads?')"><?=e($au['name'])?></button><?php endforeach?></div></div><?php endif?><?php if(can('prospecting')&&mod('prospecting')):?><button type="button" class="btn btn-sm" onclick="A.bulk('initiate','Run the website & Google audit + PDF report for the selected leads?')"><?=icon('file')?>Audit &amp; report</button><?php endif?><?php if($adm):?><button type="button" class="btn btn-sm btn-r" onclick="A.bulk('delete','Delete the selected leads and all their history?')" title="Delete"><?=icon('trash')?></button><?php endif?></form>
<?php if(!$leads):?><div class="empty"><?=icon('users','eic')?><h4><?=$total||$nf||$src?'No leads match':'No leads yet'?></h4><p><?=$nf||$src?'Try clearing the filters.':'Add a lead, import a CSV, or connect website forms and ads in Settings → Lead capture.'?></p><a class="btn btn-p" href="<?=url('lead_new')?>"><?=icon('plus')?>Add lead</a></div><?php else:?>
<div class="tw"><table class="tbl"><thead><tr><th class="cb"><input type="checkbox" data-all></th><th class="sn">#</th><th>Lead</th><th>Contact</th><th>Source</th><th>Status</th><th class="num">Deal</th><th>Follow-up</th><th>Owner</th><th></th></tr></thead><tbody><?php $sn=($pg-1)*$per;foreach($leads as $l):$sn++;$nm=$l['contact_name']?:$l['name'];$ini=mb_strtoupper(mb_substr($nm,0,1));$col=['indigo','violet','blue','sky','teal','green','amber','orange','rose','pink'][crc32($nm)%10];$late=$l['follow_up_at']&&strtotime($l['follow_up_at'])<=time()&&!in_array($l['status'],['won','lost'],true);?><tr><td class="cb"><input type="checkbox" name="ids[]" value="<?=$l['id']?>" form="bulk"></td><td class="sn"><?=$sn?></td><td><div class="who"><span class="avc c-<?=$col?>"><?=e($ini)?></span><div class="biz"><a href="<?=url('lead',['id'=>$l['id']])?>"><b><?=e($nm)?></b></a><small><?=e(implode(' · ',array_filter([$l['contact_name']&&$l['name']!==$l['contact_name']?$l['name']:$l['city'],$l['service']])))?></small><?php foreach(array_slice(array_filter(array_map('trim',explode(',',(string)$l['tags']))),0,3) as $t):?><span class="bdg c-gray sm"><?=e($t)?></span> <?php endforeach?></div></div></td><td class="ctc"><?php if($l['phone']):?><span><?=icon('phone')?><?=e($l['phone'])?></span><?php endif?><?php if($l['email']):?><span><?=icon('mail')?><?=e(mb_strimwidth($l['email'],0,28,'…'))?></span><?php endif?><?php if(!$l['phone']&&!$l['email']):?><span class="muted">—</span><?php endif?></td><td><?=srcbadge($l['source'])?><?php if($l['source_detail']):?><small class="muted ell" style="display:block;max-width:170px"><?=e($l['source_detail'])?></small><?php endif?></td><td><?=sbadge($l['status'])?></td><td class="num nowrap"><?=$l['deal_value']?money($l['deal_value']):'<span class="muted">—</span>'?></td><td class="nowrap sm <?=$late?'red':''?>"><?=$l['follow_up_at']?($late?icon('alert','xs').' ':'').date('d M, h:i A',strtotime($l['follow_up_at'])):'<span class="muted">—</span>'?></td><td class="sm nowrap"><?=$l['owner']?e($l['owner']):'<span class="muted">Unassigned</span>'?><small class="muted" style="display:block"><?=ago($l['last_activity']?:$l['created_at'])?></small></td><td class="act"><?php if($l['phone']):?><a class="ib" href="tel:<?=e(preg_replace('/[^\d+]/','',$l['phone']))?>" title="Call"><?=icon('phone')?></a><a class="ib" href="<?=e(WhatsApp::link($l['phone'],''))?>" target="_blank" rel="noopener" title="WhatsApp"><?=icon('wa')?></a><?php endif?><a class="ib" href="<?=url('lead',['id'=>$l['id']])?>" title="Open"><?=icon('eye')?></a></td></tr><?php endforeach?></tbody></table></div><?php if($pages>1):?><div class="pg"><span class="muted"><?=number_format($total)?> leads</span><?php for($i=max(1,$pg-3);$i<=min($pages,$pg+3);$i++):?><a href="<?=$qs(['p'=>$i])?>" class="<?=$i===$pg?'on':''?>"><?=$i?></a><?php endfor?></div><?php endif?><?php endif?></div>
<?php endif?>
<?php if(isset($_GET['add'])):?><script>location.replace('<?=url('lead_new')?>')</script><?php endif?>
